usage.rust:
use crate::parts::unicode_normalize::{is_normalized, normalize, Form, Options};

// Remove invisible characters, NFKC, then fold whitespace (always in this order)
let clean = normalize("\u{FEFF}ﾃﾞｰﾀ\u{3000}\u{3000}ＡＩ\u{200B} ", Options::nfkc().fold_whitespace().strip_invisible());
assert_eq!(clean, "データ AI");

// Normalization only: same as Python's unicodedata.normalize("NFC", text)
assert_eq!(normalize("e\u{301}", Options::nfc()), "\u{E9}");
assert!(is_normalized("\u{E9}", Form::Nfc));

// The result is a Cow<str>: text that is already clean is borrowed, not copied
let owned: String = clean.into_owned();
